import { loadFont as loadPoppins } from "@remotion/google-fonts/Poppins";
import React from "react";
import { AbsoluteFill, Easing, Img, interpolate, spring, staticFile, useCurrentFrame } from "remotion";

// UNYPNEUS (Leal Pneus, Vilhena/RO) · pedido "Ueliton oficina", 10/11/2026. Vídeo para painéis de mídia outdoor (DOOH):
// sem locução e sem legenda, só imagem, preço e "o pneu entrando entre os valores" (áudio do cliente). Referência de ritmo:
// vídeo da Queiroz Pneus que o cliente mandou (marca → promoção → produto com preço → endereço → contato).
// Identidade: azul UnyPneus, branco, e o amarelo/vermelho das artes de preço dele. Preços exatamente como nas artes.
// Jeito: vitrine (12 fotos) nas fotos reais do estoque e na fachada; cenas de preço com os pneus recortados das artes.

const { fontFamily: F } = loadPoppins("normal", { weights: ["600", "700", "800", "900"], subsets: ["latin", "latin-ext"] });
const { fontFamily: FI } = loadPoppins("italic", { weights: ["800", "900"], subsets: ["latin", "latin-ext"] });

export const UE_FPS = 30;
export const UE_FRAMES = Math.round(48.0 * UE_FPS);

const BLUE = "#1B2FB0";
const NAVY = "#0C1766";
const DEEP = "#08104A";
const YEL = "#FFD21A";
const RED = "#E3141B";
const WHITE = "#FFFFFF";

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const IN = Easing.bezier(0.7, 0, 0.84, 0);
const k = (t: number, a: number, d: number) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const ki = (t: number, a: number, d: number) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: IN });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const sp = (t: number, a: number, damping = 18, stiffness = 120) =>
  spring({ frame: Math.max(0, Math.round((t - a) * UE_FPS)), fps: UE_FPS, config: { damping, stiffness } });
const img = (n: string) => staticFile(`ueliton/${n}`);

// tempos das cenas (s)
// v2 (revisão do diretor): PROMOÇÃO já no primeiro segundo e cartões de preço de ~2,8 s
// v4 (pedido do cliente, 11/11): cartões de produto no estilo das artes dele, com caminhão de fundo e mais informação,
// mais tempo em cada um; vídeo de ~48 s. Começo e fim (fachada) ficaram como estavam.
const T = { estoque: 3.0, drc: 6.6, durable: 14.4, michelin: 23.4, rodas: 31.2, fachada: 38.2, final: 42.6, fim: 48.0 };

// ───────── peças ─────────
// fundo liso; a luz do centro anda devagar para a tela nunca ficar parada
const BgBlue: React.FC<{ c1?: string; c2?: string }> = ({ c1 = "#2440D2", c2 = NAVY }) => {
  const s = useCurrentFrame() / UE_FPS;
  const x = 50 + 14 * Math.sin(s * 0.9);
  const y = 48 + 10 * Math.cos(s * 0.7);
  return <AbsoluteFill style={{ background: `radial-gradient(ellipse 85% 60% at ${x}% ${y}%, ${c1} 0%, ${BLUE} 45%, ${c2} 100%)` }} />;
};

// texto que sobe da linha (máscara) e fica parado
const Rise: React.FC<{ t: number; at: number; children: React.ReactNode; d?: number }> = ({ t, at, children, d = 0.45 }) => {
  const q = k(t, at, d);
  return (
    <div style={{ overflow: "hidden", padding: "0 0.1em", lineHeight: 1.05 }}>
      <div style={{ transform: `translateY(${(1 - q) * 110}%)` }}>{children}</div>
    </div>
  );
};

const Pill: React.FC<{ t: number; at: number; text: string; bg?: string; ink?: string; size?: number }> = ({ t, at, text, bg = YEL, ink = NAVY, size = 44 }) => {
  const s = sp(t, at, 16, 200);
  return (
    <div style={{ display: "inline-block", padding: `${size * 0.16}px ${size * 0.6}px ${size * 0.2}px`, borderRadius: size, background: bg, color: ink, fontFamily: F, fontWeight: 800, fontSize: size, letterSpacing: "0.01em", whiteSpace: "nowrap", opacity: Math.min(1, s * 3), transform: `scale(${0.6 + 0.4 * s})` }}>{text}</div>
  );
};

// preço no painel vermelho inclinado, como nas artes do cliente
const Price: React.FC<{ t: number; at: number; int: string; cents: string; panel?: string }> = ({ t, at, int, cents, panel = RED }) => {
  const s = sp(t, at, 15, 170);
  const w = k(t, at, 0.35);
  return (
    <div style={{ position: "relative", width: 840, height: 220, display: "flex", alignItems: "center", justifyContent: "center" }}>
      <div style={{ position: "absolute", inset: 0, background: panel, borderRadius: 26, transform: `skewX(-9deg) scaleX(${w})`, boxShadow: "0 24px 60px rgba(0,0,0,0.35)" }} />
      <div style={{ position: "relative", display: "flex", alignItems: "flex-start", fontFamily: FI, fontStyle: "italic", fontWeight: 900, color: YEL, opacity: Math.min(1, s * 2.5), transform: `scale(${0.7 + 0.3 * s})`, textShadow: "0 6px 0 rgba(90,0,0,0.45)" }}>
        <span style={{ fontSize: 62, marginTop: 34, marginRight: 14 }}>R$</span>
        <span style={{ fontSize: 172, lineHeight: 1, letterSpacing: "-0.02em" }}>{int}</span>
        <span style={{ fontSize: 76, marginTop: 22 }}>,{cents}</span>
      </div>
    </div>
  );
};

const Head: React.FC<{ t: number; at: number; title: string; sub?: string; ink?: string; subInk?: string }> = ({ t, at, title, sub, ink = WHITE, subInk = YEL }) => (
  <div style={{ position: "absolute", left: 120, right: 120, top: 270, display: "flex", flexDirection: "column", alignItems: "center", gap: 10, textAlign: "center" }}>
    <Rise t={t} at={at}><div style={{ fontFamily: FI, fontStyle: "italic", fontWeight: 900, fontSize: 128, color: ink, letterSpacing: "-0.01em", whiteSpace: "nowrap" }}>{title}</div></Rise>
    {sub && <Rise t={t} at={at + 0.18}><div style={{ fontFamily: F, fontWeight: 800, fontSize: 48, color: subInk, whiteSpace: "nowrap" }}>{sub}</div></Rise>}
  </div>
);

// pneu entrando de lado, girando um pouco, com borrão na velocidade
const Enter: React.FC<{ t: number; at: number; from: -1 | 1 | 0; src: string; left: number; top: number; h: number; rot?: number; z?: [number, number, number]; fade?: [number, number]; fadeTop?: number; light?: boolean }> = ({ t, at, from, src, left, top, h, rot = 0, z, fade, fadeTop = 0, light }) => {
  const s = sp(t, at, 17, 110);
  const v = Math.abs(sp(t, at + 1 / UE_FPS, 17, 110) - s) * UE_FPS;
  const dx = from === 0 ? 0 : from * (1 - s) * 1150;
  const dy = from === 0 ? (1 - s) * 1300 : 0;
  const r = rot + (from === 0 ? 0 : from * (1 - s) * 28);
  const zz = z ? interpolate(t, [z[0], z[1]], [1, z[2]], cl) : 1;
  const drift = z ? lin(t, z[0], z[1]) : 0;
  return (
    <div style={{ position: "absolute", left, top, height: h, transform: `translate(${dx}px, ${dy - drift * 26}px) rotate(${r + drift * 2.5}deg) scale(${zz})`, filter: `blur(${Math.min(14, v * 2.2)}px)${light ? " brightness(1.22) contrast(1.06) drop-shadow(0 0 22px rgba(170,200,255,0.6))" : ""} drop-shadow(0 40px 50px rgba(0,0,20,0.5))`, transformOrigin: "50% 60%" }}>
      <Img src={img(src)} style={{ height: "100%", display: "block", ...(fade || fadeTop ? (() => {
        // a arte do cliente corta o pneu em cima/embaixo: a borda cortada some num esfumado (e a de baixo fica atrás do preço)
        const g = `linear-gradient(180deg, ${fadeTop ? "transparent 0%, #000 " + fadeTop + "%" : "#000 0%"}, #000 ${fade ? fade[0] : 100}%, ${fade ? "transparent " + fade[1] + "%" : "#000 100%"})`;
        return { WebkitMaskImage: g, maskImage: g };
      })() : {}) }} />
    </div>
  );
};

const PriceBlock: React.FC<{ t: number; at: number; pill?: string; int: string; cents: string; top?: number; pillSize?: number }> = ({ t, at, pill, int, cents, top = 1150, pillSize = 44 }) => (
  <div style={{ position: "absolute", left: 120, right: 120, top, display: "flex", flexDirection: "column", alignItems: "center", gap: 18 }}>
    {pill ? <Pill t={t} at={at} text={pill} size={pillSize} /> : null}
    <Price t={t} at={at + 0.2} int={int} cents={cents} />
  </div>
);

// luz suave atrás do produto: o pneu escuro não some no azul
const Spot: React.FC<{ y?: number }> = ({ y = 900 }) => (
  <div style={{ position: "absolute", left: 140, width: 800, top: y - 380, height: 760, borderRadius: "50%", background: "radial-gradient(closest-side, rgba(150,180,255,0.32), rgba(150,180,255,0))" }} />
);

// ───────── cena 1 · gancho: o amarelo toma a tela e PROMOÇÃO entra com impulso; o logo assina em cima ─────────
const LG_W = 560;
const S1: React.FC<{ t: number }> = ({ t }) => {
  const r = k(t, 0, 0.4) * 160;
  const pr = sp(t, 0.08, 14, 170);
  const rev = k(t, 0.6, 0.45);
  const cam = 1 + 0.05 * lin(t, 0, T.estoque);
  return (
    <AbsoluteFill>
      <BgBlue />
      <AbsoluteFill style={{ clipPath: `circle(${r}% at 50% 50%)` }}>
        <AbsoluteFill style={{ background: YEL }} />
        <AbsoluteFill style={{ transform: `scale(${cam})` }}>
          <div style={{ position: "absolute", left: 540 - LG_W / 2, top: 400, width: LG_W, height: (LG_W * 245) / 907, clipPath: `inset(0 ${(1 - rev) * 100}% 0 0)` }}>
            <Img src={img("logo-azul.png")} style={{ width: "100%", height: "100%" }} />
          </div>
          <div style={{ position: "absolute", left: 120, right: 120, top: 680, display: "flex", justifyContent: "center" }}>
            <div style={{ fontFamily: FI, fontStyle: "italic", fontWeight: 900, fontSize: 124, lineHeight: 1.05, color: NAVY, letterSpacing: "-0.02em", whiteSpace: "nowrap", opacity: Math.min(1, pr * 3), transform: `translateY(${(1 - pr) * 160}px) scale(${1.08 - 0.08 * pr})`, filter: `blur(${(1 - Math.min(1, pr)) * 10}px)` }}>PROMOÇÃO</div>
          </div>
          <div style={{ position: "absolute", left: 120, right: 120, top: 850, display: "flex", flexDirection: "column", alignItems: "center", gap: 54 }}>
            <Pill t={t} at={0.4} text="PNEUS E RODAS" bg={RED} ink={WHITE} size={70} />
            <Rise t={t} at={0.95}><div style={{ display: "flex", alignItems: "center", gap: 14, fontFamily: F, fontWeight: 800, fontSize: 52, color: NAVY, whiteSpace: "nowrap" }}><Pin c={RED} s={56} />VILHENA · RONDÔNIA</div></Rise>
          </div>
        </AbsoluteFill>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

const Pin: React.FC<{ c?: string; s?: number }> = ({ c = YEL, s = 60 }) => (
  <svg width={s} height={s} viewBox="0 0 24 24"><path d="M12 2C7.6 2 4 5.5 4 9.9 4 15.6 12 22 12 22s8-6.4 8-12.1C20 5.5 16.4 2 12 2zm0 11a3.2 3.2 0 1 1 0-6.4 3.2 3.2 0 0 1 0 6.4z" fill={c} /></svg>
);
const Phone: React.FC<{ s?: number }> = ({ s = 54 }) => (
  <svg width={s} height={s} viewBox="0 0 24 24"><circle cx={12} cy={12} r={12} fill={YEL} /><path d="M9.2 6.6l1.3 2.6c.2.4.1.8-.2 1.1l-.9.8c.6 1.3 1.6 2.4 2.9 3l.8-.9c.3-.3.7-.4 1.1-.2l2.6 1.3c.4.2.6.6.5 1l-.3 1.3c-.1.5-.6.9-1.1.9C10.3 17.5 6.5 13.7 6.5 8.1c0-.5.4-1 .9-1.1l1.3-.3c.2 0 .4.1.5.3z" fill={NAVY} /></svg>
);

// ───────── cena 3 · estoque de verdade (vitrine): três fotos, faixa azul embaixo ─────────
const SHOTS: { src: string; a: number; b: number; z0: number; z1: number; oy: number }[] = [
  { src: "foto-8.jpg", a: T.estoque, b: 4.2, z0: 1.12, z1: 1.03, oy: 40 },
  { src: "foto-6.jpg", a: 4.2, b: 5.4, z0: 1.03, z1: 1.12, oy: 35 },
  { src: "foto-9.jpg", a: 5.4, b: T.drc + 0.5, z0: 1.1, z1: 1.02, oy: 40 },
];
const S3: React.FC<{ t: number }> = ({ t }) => {
  return (
    <AbsoluteFill>
      <AbsoluteFill style={{ background: DEEP, overflow: "hidden" }}>
        {SHOTS.map((s, i) => {
          if (t < s.a - 0.3 || t > s.b) return null;
          const p = lin(t, s.a, s.b);
          const z = s.z0 + (s.z1 - s.z0) * p;
          const inn = i === 0 ? 1 : k(t, s.a - 0.25, 0.3);
          const tx = i === 1 ? (1 - inn) * 1080 : 0;
          const ty = i === 2 ? (1 - inn) * 1920 : 0;
          return (
            <AbsoluteFill key={i} style={{ transform: `translate(${tx}px, ${ty}px)`, filter: `blur(${(1 - inn) * 12}px)` }}>
              <Img src={img(s.src)} style={{ width: "100%", height: "100%", objectFit: "cover", transform: `scale(${z})`, transformOrigin: `50% ${s.oy}%` }} />
            </AbsoluteFill>
          );
        })}
        <div style={{ position: "absolute", left: 160, right: 160, top: 780, height: 220, borderRadius: 30, background: BLUE, transform: `scaleY(${k(t, T.estoque + 0.1, 0.35)})`, transformOrigin: "50% 50%", boxShadow: "0 30px 70px rgba(0,0,30,0.5)" }} />
        <div style={{ position: "absolute", left: 190, right: 190, top: 812, display: "flex", flexDirection: "column", alignItems: "center", gap: 6 }}>
          <Rise t={t} at={T.estoque + 0.3}><div style={{ fontFamily: F, fontWeight: 800, fontSize: 56, color: WHITE, whiteSpace: "nowrap" }}>PNEUS PARA QUEM</div></Rise>
          <Rise t={t} at={T.estoque + 0.48}><div style={{ fontFamily: FI, fontStyle: "italic", fontWeight: 900, fontSize: 72, color: YEL, whiteSpace: "nowrap" }}>NÃO PODE PARAR</div></Rise>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// ───────── cartões de produto (v4): a linha das artes do cliente ─────────
// caminhão na estrada de fundo, pneu grande à esquerda, coluna de informação à direita, benefícios e a faixa da promoção embaixo

const COL_L = 545;
const COL_W = 960 - COL_L;

const Truck: React.FC<{ t: number; a: number; b: number; flip?: boolean; ox?: number }> = ({ t, a, b, flip, ox = 50 }) => {
  const p = lin(t, a, b);
  return (
    <AbsoluteFill>
      <AbsoluteFill style={{ background: `linear-gradient(180deg, ${NAVY} 0%, ${BLUE} 55%, ${DEEP} 100%)` }} />
      <div style={{ position: "absolute", left: 0, top: 0, width: 1080, height: 1180, overflow: "hidden" }}>
        <Img src={img(flip ? "caminhao-esp.jpg" : "caminhao.jpg")} style={{ position: "absolute", height: 1180, left: `${-(1180 * 1976 / 904 - 1080) * ox / 100 - p * 70 * (flip ? -1 : 1)}px`, transform: `scale(${1.04 + 0.06 * p})`, transformOrigin: "50% 50%", filter: "blur(2px) saturate(1.1)" }} />
      </div>
      {/* azul da marca por cima da foto: o caminhão fica de fundo, a informação na frente */}
      <AbsoluteFill style={{ background: "linear-gradient(180deg, rgba(8,16,74,0.78) 0%, rgba(20,38,160,0.5) 30%, rgba(20,38,160,0.62) 50%, rgba(27,47,176,0.97) 62%, #1B2FB0 70%, #0C1766 100%)" }} />
      <AbsoluteFill style={{ background: "linear-gradient(90deg, rgba(8,16,74,0.15) 0%, rgba(8,16,74,0) 45%, rgba(8,16,74,0.45) 100%)" }} />
    </AbsoluteFill>
  );
};

// selo branco com a marca em vermelho (como o logo da marca nas artes)
const BrandTag: React.FC<{ t: number; at: number; text: string }> = ({ t, at, text }) => {
  const q = k(t, at, 0.4);
  return (
    <div style={{ clipPath: `inset(0 ${(1 - q) * 100}% 0 0)`, background: WHITE, borderRadius: 14, padding: "6px 22px 8px", transform: "skewX(-8deg)" }}>
      <div style={{ fontFamily: FI, fontStyle: "italic", fontWeight: 900, fontSize: 58, color: RED, letterSpacing: "-0.01em", whiteSpace: "nowrap", lineHeight: 1.05 }}>{text}</div>
    </div>
  );
};

// brilho que passa uma vez pela peça (só no destaque)
const Shine: React.FC<{ t: number; ats: number[] }> = ({ t, ats }) => {
  const a = ats.find((x) => t >= x && t < x + 0.7);
  if (a === undefined) return null;
  const p = (t - a) / 0.7;
  return <div style={{ position: "absolute", inset: 0, overflow: "hidden", borderRadius: "inherit", pointerEvents: "none" }}><div style={{ position: "absolute", top: -40, bottom: -40, width: 90, left: `${-20 + p * 130}%`, background: "linear-gradient(90deg, rgba(255,255,255,0), rgba(255,255,255,0.55), rgba(255,255,255,0))", transform: "skewX(-18deg)" }} /></div>;
};

const PriceCol: React.FC<{ t: number; at: number; tag: string; int: string; cents: string; shine: number[] }> = ({ t, at, tag, int, cents, shine }) => {
  const s = sp(t, at + 0.15, 15, 170);
  const w = k(t, at, 0.35);
  return (
    <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 0, width: COL_W - 30 }}>
      <div style={{ background: RED, color: WHITE, fontFamily: FI, fontStyle: "italic", fontWeight: 900, fontSize: 34, padding: "4px 20px 6px", transform: `skewX(-9deg) scaleX(${w})`, whiteSpace: "nowrap", zIndex: 2, borderRadius: 6 }}>{tag}</div>
      <div style={{ position: "relative", width: "100%", height: 150, marginTop: -6, display: "flex", alignItems: "center", justifyContent: "center", borderRadius: 22 }}>
        <div style={{ position: "absolute", inset: 0, background: RED, borderRadius: 22, transform: `skewX(-9deg) scaleX(${w})`, boxShadow: "0 22px 50px rgba(0,0,0,0.4)" }} />
        <div style={{ position: "relative", display: "flex", alignItems: "flex-start", fontFamily: FI, fontStyle: "italic", fontWeight: 900, color: YEL, opacity: Math.min(1, s * 2.5), transform: `scale(${0.7 + 0.3 * Math.min(1, s)})`, textShadow: "0 5px 0 rgba(90,0,0,0.45)" }}>
          <span style={{ fontSize: 36, marginTop: 20, marginRight: 8 }}>R$</span>
          <span style={{ fontSize: 98, lineHeight: 1, letterSpacing: "-0.03em" }}>{int}</span>
          <span style={{ fontSize: 46, marginTop: 10 }}>,{cents}</span>
        </div>
        <div style={{ position: "absolute", inset: 0, borderRadius: 22, transform: "skewX(-9deg)", overflow: "hidden" }}><Shine t={t} ats={shine} /></div>
      </div>
    </div>
  );
};

// prazo em destaque: branco com azul (pedido do cliente)
const Prazo: React.FC<{ t: number; at: number; shine: number[] }> = ({ t, at, shine }) => {
  const s = sp(t, at, 15, 180);
  return (
    <div style={{ position: "relative", width: COL_W, background: WHITE, borderRadius: 22, padding: "10px 0 14px", display: "flex", flexDirection: "column", alignItems: "center", opacity: Math.min(1, s * 3), transform: `scale(${0.75 + 0.25 * s})`, boxShadow: "0 18px 40px rgba(0,0,30,0.4)", border: `5px solid ${BLUE}`, overflow: "hidden" }}>
      <div style={{ fontFamily: F, fontWeight: 800, fontSize: 32, color: BLUE, letterSpacing: "0.06em", lineHeight: 1.1 }}>NO PRAZO</div>
      <div style={{ fontFamily: F, fontWeight: 900, fontSize: 44, color: NAVY, letterSpacing: "-0.01em", lineHeight: 1.1, whiteSpace: "nowrap" }}>20/40/60/80/100</div>
      <Shine t={t} ats={shine} />
    </div>
  );
};

const IcoTruck: React.FC<{ s?: number; c?: string }> = ({ s = 64, c = WHITE }) => (
  <svg width={s} height={s * 0.7} viewBox="0 0 64 44"><rect x={2} y={6} width={36} height={26} rx={3} fill={c} /><path d="M40 14h11l9 10v8H40z" fill={c} /><circle cx={14} cy={36} r={6} fill={NAVY} stroke={c} strokeWidth={3} /><circle cx={50} cy={36} r={6} fill={NAVY} stroke={c} strokeWidth={3} /><path d="M-6 12h6M-10 20h10" stroke={c} strokeWidth={3} /></svg>
);
const Frete: React.FC<{ t: number; at: number }> = ({ t, at }) => {
  const s = sp(t, at, 14, 190);
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 16, background: NAVY, border: `3px solid ${YEL}`, borderRadius: 18, padding: "10px 24px", opacity: Math.min(1, s * 3), transform: `scale(${0.7 + 0.3 * s})` }}>
      <IcoTruck s={70} c={YEL} />
      <div style={{ fontFamily: FI, fontStyle: "italic", fontWeight: 900, lineHeight: 0.95, fontSize: 44 }}>
        <div style={{ color: WHITE }}>FRETE</div><div style={{ color: YEL }}>PAGO</div>
      </div>
    </div>
  );
};
const Selo: React.FC<{ t: number; at: number; l1: string; l2: string }> = ({ t, at, l1, l2 }) => {
  const s = sp(t, at, 14, 190);
  return (
    <div style={{ background: YEL, borderRadius: 18, padding: "8px 26px 10px", textAlign: "center", fontFamily: FI, fontStyle: "italic", fontWeight: 900, lineHeight: 1, opacity: Math.min(1, s * 3), transform: `scale(${0.7 + 0.3 * s}) rotate(-3deg)`, boxShadow: "0 16px 36px rgba(0,0,30,0.4)" }}>
      <div style={{ fontSize: 38, color: NAVY }}>{l1}</div><div style={{ fontSize: 46, color: RED }}>{l2}</div>
    </div>
  );
};

// ícones dos benefícios (traço branco)
const SW = { fill: "none", stroke: WHITE, strokeWidth: 5, strokeLinecap: "round", strokeLinejoin: "round" } as const;
const ICONS: Record<string, React.ReactNode> = {
  estrada: <><path d="M22 54 L30 10 M42 54 L34 10" {...SW} /><path d="M32 16v6M32 30v6M32 44v6" {...SW} /></>,
  escudo: <><path d="M32 8 L52 16 V30 C52 42 43 51 32 56 C21 51 12 42 12 30 V16 Z" {...SW} /><path d="M23 31 L30 38 L42 25" {...SW} /></>,
  tracao: <><rect x={18} y={8} width={28} height={48} rx={12} {...SW} /><path d="M18 20h28M18 32h28M18 44h28" {...SW} /></>,
