// ───────── transições (uma diferente em cada troca) ─────────
const flood = (t: number, at: number, d = 0.45) => k(t, at, d) * 150;
const EIO = Easing.bezier(0.65, 0, 0.35, 1);

export const Ueliton: React.FC = () => {
  const t = useCurrentFrame() / UE_FPS;
  // DRC → Durable: a câmera mergulha no pneu da DRC e sai no Durable
  const dive = ki(t, T.durable - 0.3, 0.32);
  const land = k(t, T.durable - 0.05, 0.4);
  // Durable → Michelin: o vermelho sai da etiqueta de preço e cobre a tela; a Michelin nasce do mesmo ponto
  const redR = k(t, T.michelin - 0.4, 0.28) * 150;
  const micR = k(t, T.michelin + 0.02, 0.4) * 150;
  // Michelin → Rodas: empurra para cima
  const up = interpolate(t, [T.rodas - 0.2, T.rodas + 0.22], [0, 1], { ...cl, easing: EIO });
  // Rodas → fachada: as rodas avançam na câmera
  const thru = ki(t, T.fachada - 0.3, 0.3);
  return (
    <AbsoluteFill style={{ background: DEEP }}>
      {t >= T.estoque - 0.35 && t < T.drc + 0.5 && <S3 t={t} />}
      {t < T.estoque && (
        <AbsoluteFill style={{ transform: `translateY(${-ki(t, T.estoque - 0.35, 0.35) * 100}%)` }}>
          <S1 t={t} />
        </AbsoluteFill>
      )}
      {t >= T.drc - 0.05 && t < T.durable + 0.05 && (
        <AbsoluteFill style={{ clipPath: t < T.drc + 0.5 ? `circle(${flood(t, T.drc - 0.05)}% at 50% 100%)` : undefined, transform: `scale(${1 + dive * 2.4})`, transformOrigin: "27% 43%", filter: `blur(${dive * 16}px)`, opacity: 1 - dive * 0.6 }}>
          <SDrc t={t} />
        </AbsoluteFill>
      )}
      {t >= T.durable - 0.05 && t < T.michelin + 0.1 && (
        <AbsoluteFill style={{ transform: `scale(${1.3 - 0.3 * land})`, filter: `blur(${(1 - land) * 14}px)`, opacity: Math.min(1, land * 3) }}>
          <SDurable t={t} />
        </AbsoluteFill>
      )}
      {t >= T.michelin - 0.3 && t < T.michelin + 0.4 && (
        <AbsoluteFill style={{ background: RED, clipPath: `circle(${redR}% at 70% 38%)` }} />
      )}
      {t >= T.michelin + 0.02 && t < T.rodas + 0.25 && (
        <AbsoluteFill style={{ clipPath: t < T.michelin + 0.4 ? `circle(${micR}% at 70% 38%)` : undefined, transform: `translateY(${-up * 1920}px)`, filter: `blur(${Math.sin(up * Math.PI) * 10}px)` }}>
          <SMichelin t={t} />
        </AbsoluteFill>
      )}
      {t >= T.rodas - 0.2 && t < T.fachada && (
        <AbsoluteFill style={{ transform: `translateY(${(1 - up) * 1920}px) scale(${1 + thru * 0.6})`, filter: `blur(${Math.sin(up * Math.PI) * 10}px)`, opacity: 1 - thru }}>
          <SRodas t={t} />
        </AbsoluteFill>
      )}
      {t >= T.fachada - 0.3 && t < T.final + 0.3 && (
        <AbsoluteFill style={{ opacity: k(t, T.fachada - 0.3, 0.3), transform: `scale(${1.15 - 0.15 * k(t, T.fachada - 0.3, 0.6)})` }}>
          <S8 t={t} />
        </AbsoluteFill>
      )}
      {t >= T.final - 0.25 && <S9 t={t} />}
    </AbsoluteFill>
  );
};

